package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

public class ScopedLeftJoinIteratorTest {

	@Test
	public void rightRowsWithoutTheKeyDoNotDisableHashing() {
		AtomicInteger checks = new AtomicInteger();
		List<BindingSet> left = new ArrayList<>();
		List<BindingSet> right = new ArrayList<>();
		for (int i = 0; i < 200; i++) {
			left.add(JoinTestSupport.countingRow(checks, "k", "v" + i, "l", Integer.toString(i)));
			right.add(JoinTestSupport.row("k", "v" + i, "r", Integer.toString(i)));
		}
		right.add(JoinTestSupport.row("r", "unkeyed"));

		ScopedLeftJoinIterator iteration = new ScopedLeftJoinIterator(JoinTestSupport.step(left),
				JoinTestSupport.step(right), null, EmptyBindingSet.getInstance(),
				new QueryEvaluationContext.Minimal(null), new String[] { "k" });

		assertEquals(JoinTestSupport.referenceJoin(left, right, true), JoinTestSupport.drain(iteration));
		assertTrue(checks.get() < 1_000,
				"one unkeyed right row must not force a scan of every right row: " + checks.get());
	}

	@Test
	public void conditionIsAppliedToEveryNullPatternAndFallbackRowsRemain() {
		List<BindingSet> left = List.of(JoinTestSupport.row("k", "a", "l", "1"), JoinTestSupport.row("l", "2"),
				JoinTestSupport.row("k", "z", "l", "3"));
		List<BindingSet> right = List.of(JoinTestSupport.row("k", "a", "r", "keep"),
				JoinTestSupport.row("r", "keep"), JoinTestSupport.row("k", "a", "r", "drop"),
				JoinTestSupport.row("r", "drop"));
		Value keep = JoinTestSupport.literal("keep");
		QueryValueEvaluationStep condition = bindings -> BooleanLiteral.valueOf(keep.equals(bindings.getValue("r")));

		ScopedLeftJoinIterator iteration = new ScopedLeftJoinIterator(JoinTestSupport.step(left),
				JoinTestSupport.step(right), condition, EmptyBindingSet.getInstance(),
				new QueryEvaluationContext.Minimal(null), new String[] { "k" });

		assertEquals(JoinTestSupport.normalize(List.of(
				JoinTestSupport.row("k", "a", "l", "1", "r", "keep"),
				JoinTestSupport.row("k", "a", "l", "1", "r", "keep"),
				JoinTestSupport.row("k", "a", "l", "2", "r", "keep"),
				JoinTestSupport.row("l", "2", "r", "keep"),
				JoinTestSupport.row("k", "z", "l", "3", "r", "keep"))),
				JoinTestSupport.drain(iteration));
	}
}
